package com.bicheon.advisor.dev356; public final class Solver{public static final class Move{public final int r1,c1,r2,c2,score;Move(int a,int b,int c,int d,int s){r1=a;c1=b;r2=c;c2=d;score=s;}}public static Move choose(int[][]b,int R,int C){Move best=null;int bs=0;for(int r=0;r<R;r++)for(int c=0;c<C;c++){if(c+1<C){int s=e(b,R,C,r,c,r,c+1);if(s>bs){bs=s;best=new Move(r,c,r,c+1,s);}}if(r+1<R){int s=e(b,R,C,r,c,r+1,c);if(s>bs){bs=s;best=new Move(r,c,r+1,c,s);}}}return best;}static int e(int[][]b,int R,int C,int r1,int c1,int r2,int c2){int a=b[r1][c1],d=b[r2][c2];if(a<0||d<0||a==d)return 0;b[r1][c1]=d;b[r2][c2]=a;int n=m(b,R,C);b[r1][c1]=a;b[r2][c2]=d;return n*1000;}static int m(int[][]b,int R,int C){boolean[][]h=new boolean[R][C];for(int r=0;r<R;r++){for(int c=0;c<C;){int t=b[r][c],e=c+1;while(e<C&&t>=0&&b[r][e]==t)e++;if(t>=0&&e-c>=3)for(int x=c;x<e;x++)h[r][x]=true;c=e;}}for(int c=0;c<C;c++){for(int r=0;r<R;){int t=b[r][c],e=r+1;while(e<R&&t>=0&&b[e][c]==t)e++;if(t>=0&&e-r>=3)for(int y=r;y<e;y++)h[y][c]=true;r=e;}}int n=0;for(int r=0;r<R;r++)for(int c=0;c<C;c++)if(h[r][c])n++;return n;}}
